def emit_stream(tag, es)
  match(tag).emit_events(tag, es)
  if callback = find_callback
    callback.call(es)
  end
rescue Pipeline::OutputError => e
  @emit_error_handler.handle_emits_error(e.tag, e.es, e.error)
rescue => e
  @emit_error_handler.handle_emits_error(tag, es, e)
end

class Pipeline
  class OutputError < StandardError
    attr_reader :error, :tag, :es

    def initialize(error, tag, es)
      @error = error
      @tag = tag
      @es = es
      super(error.message)
    end
  end

  def initialize
    @filters = []
